const main=document.querySelector('main');
const safe=(v)=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
const themeToggle=document.querySelector('[data-theme-toggle]');
const themeMedia=window.matchMedia('(prefers-color-scheme: dark)');
function preferredTheme(){try{const savedTheme=localStorage.getItem('cn-theme');if(savedTheme==='light'||savedTheme==='dark')return savedTheme}catch{}return themeMedia.matches?'dark':'light'}
function applyTheme(theme,save=false){const dark=theme==='dark';document.documentElement.dataset.theme=theme;document.documentElement.style.colorScheme=theme;themeToggle.setAttribute('aria-pressed',dark);themeToggle.setAttribute('aria-label',`Switch to ${dark?'light':'dark'} mode`);themeToggle.querySelector('[aria-hidden]').textContent=dark?'☀':'◐';themeToggle.querySelector('[data-theme-label]').textContent=dark?'Light mode':'Dark mode';document.querySelector('#theme-color')?.setAttribute('content',dark?'#0f1621':'#f6f8fc');if(save){try{localStorage.setItem('cn-theme',theme)}catch{}}}
applyTheme(preferredTheme());
themeToggle.addEventListener('click',()=>applyTheme(document.documentElement.dataset.theme==='dark'?'light':'dark',true));
themeMedia.addEventListener?.('change',()=>{try{if(!localStorage.getItem('cn-theme'))applyTheme(themeMedia.matches?'dark':'light')}catch{}});
let saved=read('cn-saved',[]);if(!Array.isArray(saved))saved=[];let sector='All companies',query='';
function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{toast('Your browser could not save this. It will last for this visit only.');return false}}
function event(name,company){const entries=read('cn-events',[]);persist('cn-events',[...(Array.isArray(entries)?entries:[]),{name,company,time:new Date().toISOString()}].slice(-500))}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('visible'),3500)}
function updateSaved(){document.querySelector('#saved-count').textContent=saved.length;document.querySelectorAll('[data-save]').forEach(b=>{const yes=saved.includes(b.dataset.save);b.classList.toggle('saved',yes);b.setAttribute('aria-pressed',yes);b.setAttribute('aria-label',`${yes?'Remove':'Save'} ${window.COMPANIES.find(c=>c.id===b.dataset.save)?.name} ${yes?'from':'to'} reading list`);b.textContent=yes?'▣':'▱'})}
function toggleSaved(id){const was=saved.includes(id);saved=was?saved.filter(x=>x!==id):[...saved,id];const ok=persist('cn-saved',saved);event(was?'unsave':'save',id);updateSaved();if(location.hash==='#/saved')list(true);if(ok)toast(was?'Removed from your reading list':'Saved to your reading list on this device')}
function mono(c){return `<span class="monogram" style="--company-color:${c.color};--company-bg:${c.bg}">${safe(c.initial)}</span>`}
function saveButton(c){return `<button class="save" data-save="${c.id}" aria-label="Save ${safe(c.name)} to reading list" aria-pressed="false">▱</button>`}
function card(c){return `<article class="card"><div class="card-top">${mono(c)}${saveButton(c)}</div><div class="category">${safe(c.sector)}</div><h3><a href="#/company/${c.id}">${safe(c.name)}</a></h3><span class="ticker">NSE: ${c.ticker}</span><p>${safe(c.summary)}</p><div class="brand-row">${c.products.slice(0,3).map(p=>`<span class="brand">${safe(p[0])}</span>`).join('')}</div><div class="card-bottom"><span>◷ &nbsp; 5 min read</span><a href="#/company/${c.id}">Understand the business <span>↗</span></a></div></article>`}
function list(onlySaved=false){document.title=(onlySaved?'Reading list':'Explore companies')+' — Company Notebook';main.innerHTML=`<div class="intro"><div><div class="eyebrow">${onlySaved?'YOUR PERSONAL SHELF':'KNOW THE BUSINESS. THEN THE STOCK.'}</div><h1>${onlySaved?'Your reading list.':'Familiar products.<br>Discover their businesses.'}</h1><p>${onlySaved?'A little research, at your own pace. Saved on this device.':'Start with a name you know. Explore what it sells, how it earns money, and what deserves a closer look.'}</p></div><div class="index-number">${String(onlySaved?saved.length:COMPANIES.length).padStart(2,'0')}<small>COMPANIES TO EXPLORE</small></div></div><div class="search-wrap"><span aria-hidden="true">⌕</span><input class="search" id="search" type="search" aria-label="Search by company, brand or ticker" placeholder="Search a company, brand or ticker…" value="${safe(query)}"></div><div class="filters" aria-label="Filter by business type">${['All companies',...new Set(COMPANIES.map(c=>c.sector))].map(s=>`<button class="chip ${sector===s?'active':''}" data-sector="${safe(s)}" aria-pressed="${sector===s}">${safe(s)}</button>`).join('')}</div><div class="section-row"><h2>${onlySaved?'Saved companies':'Explore the collection'}</h2><span id="result-count" aria-live="polite"></span></div><div id="results"></div><div class="learning-strip"><span class="icon">▤</span><div><h3>A great product is only the beginning.</h3><p>Learn the five questions to ask before forming an opinion about a business.</p></div><a href="#/guide">Read the starter guide ↗</a></div>`;filterResults(onlySaved);document.querySelector('#search').addEventListener('input',e=>{query=e.target.value;filterResults(onlySaved)})}
function filterResults(onlySaved){const q=query.toLowerCase().trim();const companies=COMPANIES.filter(c=>(!onlySaved||saved.includes(c.id))&&(sector==='All companies'||c.sector===sector)&&`${c.name} ${c.ticker} ${c.products.flat().join(' ')}`.toLowerCase().includes(q));document.querySelector('#result-count').textContent=`${companies.length} ${companies.length===1?'company':'companies'} · Curated for beginners`;document.querySelector('#results').innerHTML=companies.length?`<div class="cards">${companies.map(card).join('')}</div>`:`<div class="empty"><h2>${onlySaved&&!saved.length?'Your next discovery belongs here.':'No companies found.'}</h2><p>${onlySaved&&!saved.length?'Save a company using the bookmark button to find it here later.':`Try another company or brand, or clear your filters. We currently cover ${COMPANIES.length} companies.`}</p><button class="button secondary" data-clear>Clear filters</button> ${!onlySaved?'<button class="button" data-request>Request coverage</button>':'<a class="button" href="#/">Explore companies</a>'}<div id="coverage-form"></div></div>`;updateSaved()}
function profile(c){document.title=c.name+' — Company Notebook';event('profile_open',c.id);main.innerHTML=`<a class="back" href="#/">← All companies</a><div class="profile-head">${mono(c)}<div><div class="eyebrow">${safe(c.tag||c.sector)}</div><h1>${safe(c.name)}</h1><div class="profile-meta">NSE: ${c.ticker} &nbsp; / &nbsp; ${safe(c.sector)} &nbsp; / &nbsp; 5 min read</div></div>${saveButton(c)}</div><p class="profile-lede">${safe(c.summary)}</p><div class="profile-layout"><div><section class="content-section" id="business"><div class="number">01 / THE SIMPLE EXPLANATION</div><h2>What does this company do?</h2><p>${safe(c.description)}</p><div class="ownership"><strong>Know what you own</strong>${safe(c.ownership)}</div><p class="source-note">Business reference: <a href="${c.sources[0][1]}" target="_blank" rel="noopener">${safe(c.sources[0][0])} ↗</a></p></section><section class="content-section" id="products" style="--company-color:${c.color};--company-bg:${c.bg}"><div class="number">02 / PRODUCTS & SERVICES</div><h2>Names you can connect to the business.</h2><div class="product-grid">${c.products.map(p=>`<div class="product"><strong>${safe(p[0])}</strong><span>${safe(p[1])}</span></div>`).join('')}</div><p class="source-note">${safe(c.productNote||'Selected offerings, not a complete catalogue.')} <a href="${(c.productSource||c.sources[0][1])}" target="_blank" rel="noopener">Explore the official offering ↗</a></p></section><section class="content-section" id="money"><div class="number">03 / THE BUSINESS MODEL</div><h2>Follow the money.</h2><p>${safe(c.money)}</p>${c.revenue?`<div class="revenue-chart"><div class="section-row"><h3>Revenue by business</h3><span>${safe(c.revenue.period)}</span></div>${c.revenue.values.map(([n,v])=>`<div class="revenue-row"><div><span>${safe(n)}</span><strong>${v}%</strong></div><div class="track"><div style="width:${v}%"></div></div></div>`).join('')}<p class="source-note">${safe(c.revenue.note)} <a target="_blank" rel="noopener" href="${c.revenue.source}">Source ↗</a></p></div>`:'<p class="source-note">A verified revenue split has not yet been added to this profile. Use the company’s financial reports below for reported figures.</p>'}<p class="source-note">Business-model explanation: Company Notebook editorial interpretation.</p></section><section class="content-section" id="watch"><div class="number">04 / GO ONE LEVEL DEEPER</div><h2>Three things worth watching.</h2>${c.watch.map(([n,d])=>`<div class="item"><h3>${safe(n)}</h3><p>${safe(d)}</p></div>`).join('')}<p class="source-note">Learning prompts, not an investment score.</p></section><section class="content-section" id="risks"><div class="number">05 / THE OTHER SIDE</div><h2>What could make things harder?</h2>${c.risks.map(([n,d],i)=>`<div class="item"><h3><span class="risk-num">0${i+1}</span>${safe(n)}</h3><p>${safe(d)}</p></div>`).join('')}<p class="source-note">Editorial explanations of business risks; not an exhaustive risk assessment.</p></section><section class="content-section quiz"><div class="number">A QUICK SELF-CHECK</div><h2>${safe(c.question)}</h2><details data-quiz="${c.id}"><summary>Reveal the explanation</summary><p>${safe(c.answer)}</p></details></section><section class="content-section" id="updates"><div class="number">06 / RESEARCH UPDATE</div><h2>${safe(c.update[0])}</h2><p>${safe(c.update[1])}</p><p class="source-note">Reference reviewed in September 2026. This is a curated snapshot, not a live news feed.</p></section><section class="content-section" id="sources"><div class="number">07 / CHECK THE ORIGINAL</div><h2>Go straight to the source.</h2>${c.sources.map(([name,url])=>`<a class="source-link" href="${url}" target="_blank" rel="noopener">${safe(name)} ↗</a>`).join('')}<p class="source-note">Sources reviewed in September 2026. Product availability can vary. Verify current filings before making a financial decision.</p></section><section class="content-section"><h2>Did the business make more sense?</h2><p class="note">Pilot feedback stays on this device. Export it to share with the product team.</p><div class="feedback-actions"><button class="button secondary" data-feedback="clear" data-company="${c.id}">Yes, clearer now</button><button class="button secondary" data-feedback="unclear" data-company="${c.id}">Still have questions</button><button class="button secondary" data-correction="${c.id}">Suggest a correction</button></div><div id="feedback-form"></div></section></div><aside class="profile-aside"><div class="side-panel"><h3>INSIDE THIS NOTEBOOK</h3>${[['business','The business'],['products','Products & services'],['money','How it earns money'],['watch','What to watch'],['risks','Business risks'],['updates','Research update'],['sources','Original sources']].map(([id,n])=>`<a href="#${id}" data-scroll="${id}">${n}</a>`).join('')}</div><div class="side-panel"><h3>Understanding comes first.</h3><p>A familiar product can be a starting point. It does not tell you whether the share price is attractive.</p><a href="#/guide">Read the starter guide ↗</a></div><div class="side-panel"><small>CURATED RESEARCH</small><p>Checked 15 Sep 2026<br>No live prices or recommendations.</p></div></aside></div>`;updateSaved()}
function guide(){document.title='Starter guide — Company Notebook';main.innerHTML=`<div class="guide"><div class="eyebrow">THE BEGINNER’S NOTEBOOK</div><h1>Understand the business.<br>Build your own questions.</h1><p class="profile-lede">Five questions to make company research less intimidating.</p>${[['What is the customer paying for?','Start with a simple sentence: this company earns money by selling ___ to ___. For a service business, think about the problem it solves.'],['Where does most of the money come from?','Look beyond the most recognisable brand. Revenue measures sales; profit is what remains after relevant costs. A large division by sales is not necessarily the largest source of profit.'],['What would help it grow?','More customers, higher prices, new products and greater efficiency can have different effects. Ask which explanation is supported by the company’s reports.'],['What could weaken the business?','Consider competitors, customer demand, costs and debt. Read the risks alongside the opportunity, and look for evidence that could change your view.'],['What am I still missing?','A business profile is an introduction. Financial statements, cash flow, debt, management and valuation need further research. Understanding a product does not establish whether a share is attractively priced.']].map(([h,p])=>`<section class="content-section"><h2>${h}</h2><p>${p}</p></section>`).join('')}<section class="content-section"><h2>A few useful words</h2>${[['Revenue','Money earned from selling goods or services, before subtracting expenses.'],['Operating margin','Operating profit as a percentage of revenue. Check how the company defines operating profit.'],['Cash flow','Cash moving into and out of a business. Reported profit and cash generated can differ.'],['Subsidiary','A company controlled by another company. Ownership percentage and financial reporting treatment matter.'],['Valuation','An assessment of what a business or its shares are worth, based on assumptions and evidence.'],['Reporting period','The dates covered by a financial result. It is different from the date you read the page.']].map(([h,p])=>`<details class="glossary"><summary>${h}</summary><p>${p}</p></details>`).join('')}</section><section class="content-section"><h2>Your pilot data</h2><p>Reading-list choices, feedback and basic reading events are stored only in this browser. Nothing is submitted to a research team automatically.</p><div class="feedback-actions"><button class="button" data-export>Export pilot feedback</button><button class="button secondary" data-reset>Clear pilot feedback</button></div><p class="source-note">Clearing feedback removes feedback and reading events. Your saved reading list stays intact.</p></section><a class="button" href="#/">Explore the companies ↗</a></div>`}
function route(){const hash=location.hash||'#/';query='';sector='All companies';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash===hash||(a.id==='explore-nav'&&hash.startsWith('#/company/'))));if(hash==='#/saved')list(true);else if(hash==='#/guide')guide();else if(hash.startsWith('#/company/')){const c=COMPANIES.find(c=>c.id===hash.split('/')[2]);if(c)profile(c);else main.innerHTML='<div class="empty"><h1>Company not found.</h1><p>This profile is not in our collection yet.</p><a class="button" href="#/">Explore companies</a></div>'}else list();window.scrollTo(0,0);updateSaved()}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.save)toggleSaved(b.dataset.save);if(b.dataset.sector){sector=b.dataset.sector;document.querySelectorAll('[data-sector]').forEach(x=>{x.classList.toggle('active',x.dataset.sector===sector);x.setAttribute('aria-pressed',x.dataset.sector===sector)});filterResults(location.hash==='#/saved')}if(b.hasAttribute('data-clear')){query='';sector='All companies';list(location.hash==='#/saved')}if(b.dataset.scroll){e.preventDefault();document.getElementById(b.dataset.scroll)?.scrollIntoView({behavior:'smooth'})}if(b.dataset.feedback){recordFeedback({company:b.dataset.company,rating:b.dataset.feedback});if(b.dataset.feedback==='unclear')feedbackForm('question',b.dataset.company);else toast('Feedback saved on this device. Thank you.')}if(b.dataset.correction)feedbackForm('correction',b.dataset.correction);if(b.hasAttribute('data-request'))feedbackForm('coverage',query);if(b.hasAttribute('data-export')){const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),feedback:read('cn-feedback',[]),events:read('cn-events',[])},null,2)],{type:'application/json'});const a=document.createElement('a');const url=URL.createObjectURL(blob);a.href=url;a.download='company-notebook-pilot.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}if(b.hasAttribute('data-reset')){persist('cn-feedback',[]);persist('cn-events',[]);toast('Pilot feedback and reading events cleared')}});
function recordFeedback(value){const prior=read('cn-feedback',[]);return persist('cn-feedback',[...(Array.isArray(prior)?prior:[]),{...value,time:new Date().toISOString()}])}
function feedbackForm(type,company){const target=document.querySelector(type==='coverage'?'#coverage-form':'#feedback-form');target.innerHTML=`<form class="feedback-box"><label for="feedback-text">${type==='coverage'?'Which company or brand should we cover?':type==='correction'?'What should be corrected? Please include a source if possible.':'What is still unclear?'}</label><textarea id="feedback-text" required maxlength="2000"></textarea><button class="button" type="submit">Save feedback on this device</button></form>`;const field=target.querySelector('textarea');if(type==='coverage')field.value=company;field.focus();target.querySelector('form').onsubmit=e=>{e.preventDefault();if(!field.value.trim())return;if(recordFeedback({type,company,text:field.value.trim()})){target.innerHTML='<p class="note">Saved locally. You can export feedback from the starter guide.</p>';toast('Feedback saved on this device')}}}
document.addEventListener('toggle',e=>{if(e.target.dataset?.quiz&&e.target.open)event('explanation_revealed',e.target.dataset.quiz)},true);window.addEventListener('hashchange',route);route();
// The same reading-list actions are available to compatible browser assistants.
const modelContext=document.modelContext;
if(modelContext?.registerTool){
 const lifecycle=new AbortController();
 const definitions=[{
  name:'list_companies',title:'Find covered companies',description:'Read the company collection and current device-local reading-list status. Optionally search company, brand or ticker.',inputSchema:{type:'object',properties:{query:{type:'string'}},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},
  execute(input){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).some(k=>k!=='query')||(input.query!==undefined&&typeof input.query!=='string'))throw new Error('Expected an optional text query.');const q=(input.query||'').toLowerCase().trim();return COMPANIES.filter(c=>`${c.name} ${c.ticker} ${c.products.flat().join(' ')}`.toLowerCase().includes(q)).map(c=>({id:c.id,name:c.name,ticker:c.ticker,saved:saved.includes(c.id)}))}
 },{
  name:'set_reading_list',title:'Save or remove a company',description:'Save a covered company to, or remove it from, the device-local reading list and update visible bookmark controls.',inputSchema:{type:'object',properties:{companyId:{type:'string'},saved:{type:'boolean'}},required:['companyId','saved'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},
  execute(input){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).some(k=>!['companyId','saved'].includes(k))||typeof input.saved!=='boolean'||!COMPANIES.some(c=>c.id===input.companyId))throw new Error('A covered companyId and boolean saved are required.');if(saved.includes(input.companyId)!==input.saved)toggleSaved(input.companyId);return {companyId:input.companyId,saved:saved.includes(input.companyId)}}
 }];
 for(const tool of definitions){try{Promise.resolve(modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
// Track completion locally when a reader reaches the source section.
let completionObserver;
const baseRoute=route;
function observeReading(){completionObserver?.disconnect();const el=document.querySelector('#sources');if(!el||!('IntersectionObserver' in window))return;const id=location.hash.split('/')[2];completionObserver=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){event('profile_completed',id);completionObserver.disconnect()}},{threshold:.2});completionObserver.observe(el)}
window.addEventListener('hashchange',observeReading);observeReading();
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();main.focus();main.scrollIntoView()});
